// No inputs or outputs; simply invoke the backtrace function.
// There are no documented preconditions other than it may print/log.
// We avoid any blocking behavior; function is expected to be quick.
// Call the target API.
display_backtrace();

// Validation: nothing to assert beyond successful call and non-crash.
// If implementation throws or crashes, the fuzzer will catch it.

// Construct a valid siginfo_t on the stack to satisfy non-null and validity requirements.
// We do not rely on external inputs to avoid undefined pointer usage.
siginfo_t si; // POD type; we'll zero-initialize and then set key fields.
// Clear all fields to a known baseline
memset(&si, 0, sizeof(si));

// Set a plausible, in-range signal number: [1, 64]
int signo = (int)(*FUZZ_PARAM(unsigned int) % 64u) + 1;
si.si_signo = signo;

// Set a plausible errno and code; ranges are implementation-defined, keep small.
si.si_errno = (int)(*FUZZ_PARAM(unsigned int) % 256u);
si.si_code = (int)(*FUZZ_PARAM(unsigned int) % 16u) - 8; // can be negative, implementation-defined

// Populate a few union members in a benign way to touch different branches in implementations.
// Use the generic pointer/addr field where present.
#if defined(__linux__)
  // Many libcs expose si_addr for faulting address; set to an aligned fake address.
  si.si_addr = (void*)((uintptr_t)(*FUZZ_PARAM(uintptr_t)) & ~(uintptr_t)0xF);
#endif

// Enforce non-null precondition explicitly.
FUZZ_ASSERT(&si != nullptr, "siginfo_t pointer must be non-null");

// Invoke target function with a valid pointer to siginfo data.
backtrace_handle_signal(&si);

// Validation: We ensured a non-null, initialized siginfo_t and called the function.
// No outputs are produced; any side-effects (logging/backtrace) are acceptable in fuzzing.
